CREATE TABLE IF NOT EXISTS legal_wiki.reference_job_mappings(job_id bigint PRIMARY KEY REFERENCES legal_wiki.ingestion_jobs(id),target text NOT NULL CHECK(target IN ('eflaw','prec')),external_id text NOT NULL CHECK(external_id ~ '^[1-9][0-9]{0,19}$'),confirmed_by text NOT NULL CHECK(length(btrim(confirmed_by))>0),confirmed_at timestamptz NOT NULL DEFAULT now(),evidence_url text NOT NULL CHECK(evidence_url ~ '^https://(www[.])?law[.]go[.]kr/'));
